    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    row_dividers = [r for r in range(h) if all(v == 8 for v in g[r])]
    col_dividers = [c for c in range(w) if all(g[r][c] == 8 for r in range(h))]

    def tile_spans(length, dividers):
        spans, start = [], 0
        for cut in dividers:
            if start < cut:
                spans.append((start, cut))
            start = cut + 1
        if start < length:
            spans.append((start, length))
        # Partial trailing cells are just borders, not tiles to be colored.
        if spans:
            size = spans[0][1] - spans[0][0]
            spans = [(a, b) for a, b in spans if b - a == size]
        return spans

    rows = tile_spans(h, row_dividers)
    cols = tile_spans(w, col_dividers)
    seeds = {2: [], 3: []}
    for ri, (r0, r1) in enumerate(rows):
        for ci, (c0, c1) in enumerate(cols):
            for color in seeds:
                if any(g[r][c] == color for r in range(r0, r1) for c in range(c0, c1)):
                    seeds[color].append((ri, ci))

    # Each color joins aligned same-color markers with a straight segment.
    painted = {2: set(), 3: set()}
    for color, points in seeds.items():
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        painted[color].add((r1, c))
                elif c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        painted[color].add((r, c1))

    for ri, (r0, r1) in enumerate(rows):
        for ci, (c0, c1) in enumerate(cols):
            p2, p3 = (ri, ci) in painted[2], (ri, ci) in painted[3]
            color = 6 if p2 and p3 else 2 if p2 else 3 if p3 else None
            if color is not None:
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        g[r][c] = color
    return g

